package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.ai.infrastructure.*;import com.yuegang.zhihui.ai.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class AiConfiguration{@Bean ModelGateway modelGateway(@Value("${ygh.ai.doubao-base-url}")String b,@Value("${ygh.ai.doubao-api-key}")String k,@Value("${ygh.ai.chat-model}")String m){return new DoubaoModelGateway(b,k,m);}@Bean RetrievalGateway retrievalGateway(@Value("${ygh.ai.search-base-url}")String b,@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new HttpRetrievalGateway(b,k);}finally{Arrays.fill(k,(byte)0);}}@Bean ChatService chatService(RetrievalGateway r,ModelGateway m,DataSource d){return new ChatService(r,m,d);}@Bean AiUserResolver aiUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new AiUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
